from moler.exceptions import ParsingDone

from ta_moler.cmd.egate.generictabcontent import GenericTabContent

__author__ = 'Adrianna Pienkowska'
__copyright__ = 'Copyright (C) 2018, Nokia'
__email__ = 'adrianna.pienkowska@nokia.com'


class SeqDisp(GenericTabContent):
    """Seqdisp command class."""

    def __init__(self, connection, ue_id=None, device=None, prompt=None, newline_chars=None, runner=None):
        """
        Seqdisp command.

        :param connection: moler connection to device, terminal when command is executed.
        :param ue_id: id of ue.
        :param device: name of device.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(SeqDisp, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.ue_id = ue_id
        self.device = device
        self._add_list = True
        self._add_dict = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = 'seq_disp'
        if self.ue_id:
            cmd = f'{cmd} id={self.ue_id}'
        if self.device:
            cmd = f'{cmd} at={self.device}'
        return cmd

    def _parse_data_row(self, line):
        try:
            super(SeqDisp, self)._parse_data_row(line)
        except ParsingDone:
            self.current_ret['LIST'][-1]['Id'] = int(self.current_ret['LIST'][-1]['Id'])
            self.current_ret['LIST'][-1]['UE Group'] = int(self.current_ret['LIST'][-1]['UE Group'])
            raise


